function d_symreg(P,R){var n=P.n||40,x=[],y=[];var a=P.a||2.5,b=P.b||-1.2,c=P.c||3.0;for(var i=0;i<n;i++){var xi=-3+6*i/(n-1);x.push(xi);y.push(a*xi*xi+b*xi+c+(R()-0.5)*2);}var sx=0,sx2=0,sx3=0,sx4=0,sy=0,sxy=0,sx2y=0;for(i=0;i<n;i++){var v=x[i];sx+=v;sx2+=v*v;sx3+=v*v*v;sx4+=v*v*v*v;sy+=y[i];sxy+=v*y[i];sx2y+=v*v*y[i];}function det3(m){return m[0][0]*(m[1][1]*m[2][2]-m[1][2]*m[2][1])-m[0][1]*(m[1][0]*m[2][2]-m[1][2]*m[2][0])+m[0][2]*(m[1][0]*m[2][1]-m[1][1]*m[2][0]);}var M=[[sx4,sx3,sx2],[sx3,sx2,sx],[sx2,sx,n]],d0=det3(M);function rep(M2,col,vec){var c2=M2.map(function(r){return r.slice();});for(var k=0;k<3;k++)c2[k][col]=vec[k];return det3(c2);}var V=[sx2y,sxy,sy];var A=rep(M,0,V)/d0,B=rep(M,1,V)/d0,C=rep(M,2,V)/d0;var ym=sy/n,ss=0,sr=0;for(i=0;i<n;i++){ss+=(y[i]-ym)*(y[i]-ym);var f=A*x[i]*x[i]+B*x[i]+C;sr+=(y[i]-f)*(y[i]-f);}var r2=1-sr/Math.max(1e-9,ss);return{true_coeffs:[a,b,c],found:[+A.toFixed(4),+B.toFixed(4),+C.toFixed(4)],r_squared:+r2.toFixed(5),model:'y = A*x^2 + B*x + C'};}

